/// <reference lib="webworker" />
import { precacheAndRoute, cleanupOutdatedCaches } from 'workbox-precaching';
import { clientsClaim } from 'workbox-core';

declare let self: ServiceWorkerGlobalScope;

self.skipWaiting();
clientsClaim();

// Precache default assets generated by Vite PWA
precacheAndRoute(self.__WB_MANIFEST || []);
cleanupOutdatedCaches();

const RUNTIME_CACHE = 'servos-runtime-v5';
const SHELL_CACHE_KEY = '/__app_shell__';

self.addEventListener('activate', (event: ExtendableEvent) => {
    event.waitUntil(
        caches.keys().then((keys) =>
            Promise.all(
                keys
                    .filter((k) => k.startsWith('servos-runtime-') && k !== RUNTIME_CACHE)
                    .map((k) => caches.delete(k))
            )
        )
    );
});

// Cache inteligente para economizar dados móveis (Fontes, Imagens de Formação, Ícones e App Shell offline)
self.addEventListener('fetch', (event: FetchEvent) => {
    const req = event.request;
    if (req.method !== 'GET') return;

    const url = new URL(req.url);

    // 0. Navegação SPA (ex: abrir /escalas?checkin=SACRISTIA_ST_2026 offline) -> Network-First com fallback offline
    if (req.mode === 'navigate' && url.origin === self.location.origin) {
        event.respondWith(
            caches.open(RUNTIME_CACHE).then(async (cache) => {
                try {
                    const netRes = await fetch(req);
                    if (netRes && netRes.status === 200) {
                        cache.put(SHELL_CACHE_KEY, netRes.clone());
                    }
                    return netRes;
                } catch {
                    const cachedShell = await cache.match(SHELL_CACHE_KEY);
                    return cachedShell || Response.error();
                }
            })
        );
        return;
    }

    // 1. Cache-First para Fontes do Google e Imagens estáticas (/formacao/, ícones, etc.)
    const isFont = url.origin.includes('fonts.googleapis.com') || url.origin.includes('fonts.gstatic.com');
    const isStaticImage =
        url.origin === self.location.origin &&
        (/\.(png|jpg|jpeg|webp|svg|ico)$/i.test(url.pathname) || url.pathname.startsWith('/formacao/'));

    if (isFont || isStaticImage) {
        event.respondWith(
            caches.open(RUNTIME_CACHE).then(async (cache) => {
                const cached = await cache.match(req);
                if (cached) return cached;
                try {
                    const netRes = await fetch(req);
                    if (netRes && netRes.status === 200) {
                        cache.put(req, netRes.clone());
                    }
                    return netRes;
                } catch (err) {
                    return cached || Response.error();
                }
            })
        );
        return;
    }

    // 2. Stale-While-Revalidate para pacotes JS/CSS da aplicação
    const isAppAsset =
        url.origin === self.location.origin &&
        url.pathname.startsWith('/assets/') &&
        /\.(js|css)$/i.test(url.pathname);

    if (isAppAsset) {
        event.respondWith(
            caches.open(RUNTIME_CACHE).then(async (cache) => {
                const cached = await cache.match(req);
                const fetchPromise = fetch(req)
                    .then((netRes) => {
                        if (netRes && netRes.status === 200) {
                            cache.put(req, netRes.clone());
                        }
                        return netRes;
                    })
                    .catch(() => cached || Response.error());

                return cached || fetchPromise;
            })
        );
    }
});

// Listen for Web Push Notifications
self.addEventListener('push', (event) => {
    if (event.data) {
        let data;
        try {
            data = event.data.json();
        } catch (e) {
            data = { title: "Notificação", body: event.data.text() };
        }

        const title = data.title || "Notificação";
        const options: NotificationOptions & { vibrate?: number[] } = {
            body: data.body,
            icon: "/pwa-192x192.png",
            badge: "/pwa-192x192.png",
            vibrate: [200, 100, 200],
            data: {
                url: self.registration.scope
            }
        };

        event.waitUntil(self.registration.showNotification(title, options));
    }
});

self.addEventListener('notificationclick', (event) => {
    event.notification.close();
    event.waitUntil(
        self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then((clientList) => {
            const urlToOpen = new URL(event.notification.data?.url || '/', self.location.origin).href;

            for (const client of clientList) {
                if (client.url === urlToOpen && 'focus' in client) {
                    return client.focus();
                }
            }
            if (self.clients.openWindow) {
                return self.clients.openWindow(urlToOpen);
            }
        })
    );
});
